# Contratos de diseño: no son esquemas de los datos ausentes ni implementaciones.
def field(name,typ,meaning,origin,unit=None,nullable=False):
    return dict(nombre=name,tipo=typ,significado=meaning,unidad=unit,nullable=nullable,origen=origin)
def common():
    return [field('objeto_id','string','Identidad local estable de esta entidad; no PID externo.','Registro propuesto'),field('version','string','Versión inmutable; cambio crea versión con padre identificable.','Registro propuesto'),field('fuentes_versionadas','array<object>','Identidades, versiones, localizadores y huellas de fuentes utilizadas, sin duplicar como corroboraciones.','Recepción y transformaciones'),field('nulos_motivos','object','Mapa campo→DESCONOCIDO/NO_APLICA/NO_APORTADO/RESTRINGIDO y explicación; vacío solo cuando no hay nulos.','Responsable de recepción/revisión')]
contracts=[]
def contract(i,name,purpose,fields,controls,limits):
    contracts.append(dict(id=f'T01-C{i:03}',nombre=name,proposito=purpose,campos=common()+fields,controles=controls,procedencia_versiones='Cada salida conserva identidad/versiones de entradas, actividad, configuración, responsable funcional por confirmar, fecha de transformación y huella de archivo cuando exista. No sobrescribir originales. Unidad null en identificadores/textos/estados significa no pertinente; en geometría/tiempo/calidad significa desconocida o expresada en subcampo explícito y exige motivo.',limites='CONTRATO_PROPUESTO, sin instancia de datos de producto ni conformidad normativa ejecutada. '+limits))
