R['seleccion_portafolio']=dict(criterios=[dict(criterio='Relevancia decisional',uso='Identificar qué se decide mejor o se acota; no maximizar número de pantallas o historias enlazadas.'),dict(criterio='Beneficio potencial y alternativas suficientes',uso='Comparar con notas, calendario, cuaderno y conversación existentes antes de añadir software; ningún impacto medido.'),dict(criterio='Información y restricciones',uso='Fuentes necesarias, permisos, desconocidos y condiciones situadas que podrían impedir una función.'),dict(criterio='Carga y mantenimiento',uso='Quién selecciona, confirma y mantiene y si el esfuerzo tiene sentido para quienes aportan, sin posturas atribuidas ni presupuesto inventado.'),dict(criterio='Verificabilidad',uso='Ensayos acotados que puedan mostrar utilidad, daño de interpretación, insuficiencia o descarte; no aceptación por pasar validador.')],argumento='Tres candidatos cubren decisiones diferentes y conservan prácticas fuera del portafolio. P001 tiene relación más directa con revisión territorial del encargo, pero tampoco prueba necesidad de nueva plataforma. P003 comparte organización por lugar con P001, aunque sus compromisos y autorías no se fusionan. P002 aporta disciplina de unidad/evidencia y puede seguir siendo cuaderno de investigación fuera de producto público. No hay ranking empírico de necesidades urbanas.',comparacion_condicional=[dict(producto='T01-P001',prioridad='Primera conversación de pertinencia institucional, condicionada a acceso y responsable.',razon='Revisión de registros y último cambio tienen decisión acotada y criterios claros; historial básico no exige las capas SSC. Extensión espacial tiene más dependencias y se deja separable.'),dict(producto='T01-P002',prioridad='Sin orden total frente a P003; opción documental con factibilidad de seguimiento pendiente.',razon='Comparar dos ocasiones puede reducir afirmaciones; requiere aportación voluntaria nueva y responsabilidad académica. No imponer servicio institucional para investigación privada.'),dict(producto='T01-P003',prioridad='Candidata a ensayo de relevo solo si varias personas retoman espacios.',razon='Puede probarse con notas/calendario y revisión de lenguaje; no demanda migrar comunicación ni convertir ritmos en perfil comunitario.')],pendientes=['Contrastar con personas/roles pertinentes el valor frente a prácticas actuales, sin contactar en T01.','Identificar responsable, permisos, producción de soportes, carga y presupuesto real antes de planear implementación.','N005 queda condición pendiente sin historia; no entra por ampliar el catálogo de datos. H017 y H021 se conservan explícitamente, sin pérdida de legitimidad por quedar fuera.','Adopción por ADIP/otras instituciones, selección de producto público y acceso a SSC no aprobados ni inferidos.'])
R['extension_fair_janus']=dict(medidas=[dict(area='Localización e identidad',accion='Reusar ids canónicos y referencias del paquete; conservar ruta/version/huella de entradas y derivados. Identificadores T01 locales estables, sin PID/DOI inventado.',estado='REGISTRO_LOCAL_REAL; RESOLUCION_PERSISTENTE_PENDIENTE'),dict(area='Acceso, licencia y metadatos',accion='Separar permiso de lectura, licencia de contenido, metadatos de conocimiento y del artefacto, e identidad/custodia física. No licenciar corpus con MIT ni publicar datos por cumplir trazabilidad.',estado='PROPUESTA_DE_DATOS; ARCHIVOS_T01_CON_METADATOS_LOCALES'),dict(area='Interoperabilidad y procedencia',accion='Diccionarios por contrato y correspondencias versionadas de entidades/tiempo/espacio. Evaluar PROV-O Entity/Activity/Agent/derivación; no imponer vocabulario a diferencias legítimas.',estado='CONTRATOS_PROPUESTOS; RDF_NO_IMPLEMENTADO'),dict(area='Reutilización y empaquetado',accion='Tablas completas derivadas, scripts usados, registro de consulta y huellas reales permiten revisar diseño. RO-Crate requeriría descriptor, entidades y validación; DataCite y nanopublicaciones requieren selección de contenido, permisos y esquema consultado antes de implementarlos.',estado='PAQUETE_LOCAL_REAL; RO_CRATE_DATACITE_NANOPUBLICACIONES_PROPUESTOS'),dict(area='Adaptación JANUS',accion='Conservar instrucciones de análisis/integración, archivos de entrada/salida, versiones, estrategia de consulta dirigida, decisiones y limitaciones. Registro de controles mecánicos y revisión asistida separado de revisión humana.',estado='REGISTRO_T01_REAL; REVISION_INDEPENDIENTE_PENDIENTE')],objetos_afectados=['Necesidades/historias/códigos y metadatos de HU01/N01 reutilizados sin recodificación; no se modifica corpus.','Diseño, productos candidatos, contratos, diagramas y salidas documentales T01.','Datos operativos y fuentes situadas futuras, aún no recibidos ni implementados.'],controles_propuestos=['Revisar correspondencia dato→significado→unidad→fuente y permisos de cada nueva incorporación.','Si se adopta RO-Crate/PROV/DataCite, crear archivo real y aplicar control de sintaxis/semántica y accesos antes de declarar conformidad; T01 no lo hace.','Revisión humana independiente/adversarial de interpretaciones y criterios; no sustituir con repetición de LLM ni calcular concordancia sin codificaciones independientes.','En repositorio final excluir prompts de desarrollo de entrevistas. Este soporte conserva solo instrucciones de tarea y registro de prompts de análisis/integración T01.'],estados_pendientes=['Revisión humana independiente, evaluación ética/contextual y aceptación.','FAIR integral, FDO, interoperabilidad operativa, publicación, PIDs y validación de productos.','Documentos originales JANUS y clase no redistribuidos: se aplica síntesis del expediente, sin afirmar lectura de esos originales.'],limites='SHA-256 acredita integridad, no verdad externa. Un ZIP o JSON no acredita por sí solo FAIR/FDO o conformidad JANUS. No se publicaron, registraron PIDs ni contactaron terceros.')
